with cleaned as (select id, product_name, category, cost, launch_date, tags, supplier_id, date_format(launch_date, 'yyyy-MM') as launch_date_label, lower(brand) as brand_lower, coalesce(brand, 'DIRECT') as brand_filled from products where launch_date > to_date('2024-01-29')), with_last as (select s.*, top1.last_restock, top1.quantity from cleaned s left join lateral (select c.last_restock, c.quantity from inventory c where c.product_id = s.id and c.last_restock <= s.launch_date order by c.last_restock desc, c.id desc limit 1) top1 on true), eligible as (select s.* from with_last s where not exists (select 1 from order_items x where x.product_id = s.id and x.order_id = 39)), eligible_products as (select s.* from eligible s where exists (select 1 from order_items x where x.product_id = s.id and x.order_id in (12, 13, 18, 27))) select id, product_name, category, cost, tags, supplier_id, brand_lower, brand_filled, quantity from eligible_products;
